const guides={space:{topic:'SPACE',number:'01',title:'강한 한 방 전에,<br>빈 공간이 먼저 생깁니다.',description:'상대를 코트 뒤로 밀어낸 다음, 네트 앞에 짧게 떨어뜨리는 공을 찾아보세요. 득점 순간을 되돌려 보면, 그 전에 상대를 움직인 공이 보입니다.',tip:'득점 직전 두 번의 샷에서 상대가 어디로 이동했는지 보세요.',alt:'상대를 뒤로 보낸 뒤 앞쪽 빈 공간을 공략하는 관전 개념도'},recovery:{topic:'RECOVERY',number:'02',title:'좋은 샷 다음에는,<br>좋은 준비가 이어집니다.',description:'공을 받아낸 뒤 선수가 어디로 돌아오는지 따라가 보세요. 상대가 보낼 수 있는 다음 공에 대비해, 다시 움직일 수 있는 위치와 자세를 만드는 과정입니다.',tip:'어려운 공을 받은 선수가 다음 샷 전에 균형을 되찾는지 보세요.',alt:'샷을 친 뒤 다음 공을 준비할 위치로 돌아오는 관전 개념도'},tempo:{topic:'TEMPO',number:'03',title:'빠르게, 때로는 느리게.<br>리듬도 하나의 전략입니다.',description:'긴 공으로 시간을 만들고, 짧은 공으로 상대를 앞으로 부르는 장면을 찾아보세요. 비슷하게 이어지던 랠리에서 길이와 속도가 달라지는 순간에 주목해보세요.',tip:'공의 길이나 속도가 바뀐 직후, 상대의 자세가 어떻게 달라지는지 보세요.',alt:'긴 공과 짧은 공을 섞어 랠리의 흐름을 바꾸는 관전 개념도'}};
window.dataLayer=window.dataLayer||[];
function track(event,properties={}){window.dataLayer.push({event,...properties})}
const tabs=[...document.querySelectorAll('[data-guide]')];
function selectGuide(button){const name=button.dataset.guide;const guide=guides[name];tabs.forEach(tab=>{const active=tab===button;tab.classList.toggle('active',active);tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1});document.querySelector('#guide-panel').setAttribute('aria-labelledby',button.id);document.querySelector('#diagram-topic').textContent=guide.topic;document.querySelector('#guide-kicker').textContent=`${guide.number} / ${guide.topic}`;document.querySelector('#guide-title').innerHTML=guide.title;document.querySelector('#guide-description').textContent=guide.description;document.querySelector('#guide-tip').textContent=guide.tip;document.querySelector('#court-title').textContent=guide.alt;Object.keys(guides).forEach(key=>{document.querySelector(`.court-${key}`).toggleAttribute('hidden',key!==name)});track('guide_select',{guide_name:name})}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectGuide(tab));tab.addEventListener('keydown',event=>{let next;if(event.key==='ArrowRight'||event.key==='ArrowDown')next=(index+1)%tabs.length;if(event.key==='ArrowLeft'||event.key==='ArrowUp')next=(index+tabs.length-1)%tabs.length;if(event.key==='Home')next=0;if(event.key==='End')next=tabs.length-1;if(next!==undefined){event.preventDefault();selectGuide(tabs[next]);tabs[next].focus()}})});
const menuButton=document.querySelector('.menu-toggle');const mobileMenu=document.querySelector('#mobile-menu');
function closeMenu(){mobileMenu.hidden=true;menuButton.setAttribute('aria-expanded','false');menuButton.setAttribute('aria-label','메뉴 열기')}
menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));menuButton.setAttribute('aria-label',open?'메뉴 닫기':'메뉴 열기');mobileMenu.hidden=!open});
mobileMenu.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!mobileMenu.hidden){closeMenu();menuButton.focus()}});
document.querySelectorAll('[data-track]').forEach(link=>link.addEventListener('click',()=>track(link.dataset.track,{cta_location:link.dataset.location,cta_text:link.textContent.trim().replace(/\s+/g,' '),destination_url:link.href})));
document.querySelectorAll('.faq-list details').forEach((item,index)=>item.addEventListener('toggle',()=>{if(item.open)track('faq_open',{question_index:index+1})}));
track('landing_view',{page_topic:'badminton_womens_singles'});
